  circle(-18*sc, -30*sc, 7.5*sc);
  circle( 18*sc, -30*sc, 7.5*sc);

  // neck
  fill(P.skin);
  rect(-3*sc, -64*sc, 6*sc, 6*sc);
  // head
  fill(P.skin);
  circle(0, -71*sc, 19*sc);
