const hue = (frameCount * 1.5) % 360;
fill(hue, 70, 100, 8); noStroke();
triangle(0, 0, cos(a-0.05)*width, sin(a-0.05)*height, cos(a+0.05)*width, sin(a+0.05)*height);
blendMode(BLEND);
pop();

push();
translate(width/2, height*0.28);
blendMode(ADD);
const beat = frameCount / 28.8;
const pulse = pow(sin(beat * TAU), 4);
noStroke();
for (let i = 0; i < 4; i++) {
  const a = i * TAU/4 + frameCount * 0.006;
  const hue = (i * 90 + frameCount * 1.5) % 360;
  fill(hue, 70, 100, 8 + pulse * 10);
  const len = max(width,height)*0.8;
  triangle(0,0, cos(a-0.04)*len, sin(a-0.04)*len, cos(a+0.04)*len, sin(a+0.04)*len);
}
blendMode(BLEND); pop();

push();
const beat = frameCount / 28.8;
const floorY = height * 0.70;
const tileSize = width / 10;
noStroke();
for (let i = 0; i < 10; i++) {
  for (let j = 0; j < 4; j++) {
    const x = i * tileSize; const y = floorY + j * tileSize;
    const tilePulse = pow(max(0, sin((beat-(i+j)*0.15)*TAU)), 6);
    if ((i+j)%2===0) { const h=(i*36+frameCount*1.5)%360; fill(h, 40+tilePulse*30, 12+tilePulse*30); }
    else fill(0,0, 5+tilePulse*8);
    rect(x, y, tileSize, tileSize);
  }
}
pop();

push();
const beat = frameCount / 28.8;

// disco floor — bottom 30% of screen
const floorY = height * 0.70;
const tileSize = width / 10;

noStroke();
for (let i = 0; i < 10; i++) {
  for (let j = 0; j < 4; j++) {
    const x = i * tileSize;
    const y = floorY + j * tileSize;

    // checkerboard base with beat-synced color pulses
    const isLight = (i + j) % 2 === 0;
    const tileBeat = beat - (i + j) * 0.15;
    const tilePulse = pow(max(0, sin(tileBeat * TAU)), 6);

    if (isLight) {
      const h = (i * 36 + j * 90 + frameCount * 2) % 360;
      fill(h, 60 + tilePulse * 30, 30 + tilePulse * 60);
    } else {
      fill(0, 0, 8 + tilePulse * 15);
    }
    rect(x, y, tileSize, tileSize);
  }
}
pop();

push();
const beat = frameCount / 28.8;
const pulse = pow(sin(beat * TAU), 4);

translate(width/2, height * 0.28);
blendMode(ADD);
noFill();

// 8 symmetric beams rotating from disco ball
const numBeams = 8;
const beamLen = max(width, height) * 0.9;
for (let i = 0; i < numBeams; i++) {
  const a = i * TAU / numBeams + frameCount * 0.008;
  const hue = (i * 360 / numBeams + frameCount * 1.5) % 360;

  // beam cone — wider at the end
  const x1 = cos(a) * beamLen;
  const y1 = sin(a) * beamLen;
  const spread = 0.06;
  const x2 = cos(a - spread) * beamLen;
  const y2 = sin(a - spread) * beamLen;
  const x3 = cos(a + spread) * beamLen;
  const y3 = sin(a + spread) * beamLen;

  const alpha = 12 + pulse * 18;
  fill(hue, 70, 100, alpha);
  noStroke();
  triangle(0, 0, x2, y2, x3, y3);
}

blendMode(BLEND);
pop();

push();
translate(width/2, height * 0.50);

const beat = frameCount / 28.8;

// concentric rings pulsing outward on each beat
noFill();
for (let i = 0; i < 6; i++) {
  const ringBeat = beat - i * 0.5;
  const expand = (ringBeat % 4) / 4;
  const r = expand * min(width, height) * 0.55;
  const alpha = (1 - expand) * 80;
  if (alpha < 2) continue;

  const hue = (i * 60 + frameCount * 2) % 360;
  stroke(hue, 75, 100, alpha);
  strokeWeight(2.5 - expand * 1.5);
  circle(0, 0, r * 2);
}
noStroke();
pop();

push();
translate(width/2, height * 0.50);

const beat = frameCount / 28.8;
const kick = pow(sin(beat * TAU), 8);

// starburst lines — symmetric, pulsing on kick
stroke(0, 0, 100, kick * 60 + 8);
strokeWeight(1);
const rays = 24;
for (let i = 0; i < rays; i++) {
  const a = i * TAU / rays;
  const len = 80 + kick * 200 + sin(frameCount * 0.03 + i * 0.5) * 40;
  const x = cos(a) * len;
  const y = sin(a) * len;
  line(0, 0, x, y);
}

// inner rotating star
noFill();
stroke(45, 80, 100, 50);
strokeWeight(1.5);
push();
rotate(frameCount * 0.01);
beginShape();
for (let i = 0; i < 12; i++) {
  const a = i * TAU / 12;
  const r = (i % 2 === 0) ? 50 + kick * 30 : 25 + kick * 15;
  vertex(cos(a) * r, sin(a) * r);
}
endShape(CLOSE);
pop();

// counter-rotating star
stroke(280, 70, 100, 40);
push();
rotate(-frameCount * 0.008);
beginShape();
for (let i = 0; i < 16; i++) {
  const a = i * TAU / 16;
  const r = (i % 2 === 0) ? 90 + kick * 40 : 55 + kick * 20;
  vertex(cos(a) * r, sin(a) * r);
}
endShape(CLOSE);
pop();

noStroke();
pop();

push();
translate(width/2, height * 0.28);

const beat = frameCount / 28.8;
const pulse = pow(sin(beat * TAU), 4);

// outer glow pulsing on beat
blendMode(ADD);
noStroke();
for (let r = 8; r > 0; r--) {
  fill(0, 0, 100, pulse * 4 + 2);
  circle(0, 0, 140 + r * 20);
}
blendMode(BLEND);

// disco ball sphere — rows of reflective tiles
const ballR = 60 + pulse * 8;
const rows = 10;
for (let j = 0; j < rows; j++) {
  const lat1 = PI * j / rows - HALF_PI;
  const lat2 = PI * (j + 1) / rows - HALF_PI;
  const y1 = sin(lat1) * ballR;
  const y2 = sin(lat2) * ballR;
  const r1 = cos(lat1) * ballR;
  const r2 = cos(lat2) * ballR;
  const cols = max(4, floor(12 * cos((lat1 + lat2) / 2)));

  for (let i = 0; i < cols; i++) {
    const a1 = TAU * i / cols + frameCount * 0.015;
    const a2 = TAU * (i + 1) / cols + frameCount * 0.015;
    const shimmer = noise(i * 0.3, j * 0.3, frameCount * 0.03);
    const b = lerp(35, 100, shimmer);
    const h = (i * 30 + j * 20 + frameCount * 2) % 360;
    fill(h, 25, b);
    stroke(0, 0, 50, 30);
    strokeWeight(0.5);
    beginShape();
    vertex(cos(a1) * r1, y1);
    vertex(cos(a2) * r1, y1);
    vertex(cos(a2) * r2, y2);
    vertex(cos(a1) * r2, y2);
    endShape(CLOSE);
  }
}
noStroke();
pop();

push();
const beat = frameCount / 28.8;

// symmetric sparkle particles — mirrored on both sides
if (!window.state._dsp) window.state._dsp = [];
const sp = window.state._dsp;

const kick = pow(sin(beat * TAU), 8);
// emit on beat
if (kick > 0.5 && sp.length < 400) {
  for (let k = 0; k < 6; k++) {
    const a = random(TAU);
    const spd = random(1, 5);
    sp.push({
      x: cos(a) * 20, y: sin(a) * 20,
      vx: cos(a) * spd, vy: sin(a) * spd,
      hue: (beat * 90 + random(60)) % 360,
      life: 120 + random(80)
    });
  }
}

noStroke();
blendMode(ADD);
// draw mirrored from center
const cx = width / 2, cy = height * 0.50;
for (let i = sp.length - 1; i >= 0; i--) {
  const p = sp[i];
  p.x += p.vx; p.y += p.vy;
  p.vy += 0.02;
  p.life -= 1.5;
  if (p.life <= 0) { sp.splice(i, 1); continue; }
  const alpha = p.life / 200 * 80;
  const sz = map(p.life, 0, 200, 1, 5);
  fill(p.hue, 80, 100, alpha);
  // mirror 4 ways for symmetry
  circle(cx + p.x, cy + p.y, sz);
  circle(cx - p.x, cy + p.y, sz);
  circle(cx + p.x, cy - p.y, sz);
  circle(cx - p.x, cy - p.y, sz);
}
blendMode(BLEND);
pop();

push();
const beat = frameCount / 28.8;
const kick = pow(sin(beat * TAU), 4);
const floorY = height * 0.74;

// Backup dancers — uniform white outfits, smaller, flanking
const backups = [
  { xFrac:0.10, sc:1.2, skin:[25,40,85],  shirt:[0,0,95],  pants:[0,0,95],  hair:[0,0,12],   belt:[0,0,70],  wave:0.4, solo:false },
  { xFrac:0.90, sc:1.2, skin:[25,40,85],  shirt:[0,0,95],  pants:[0,0,95],  hair:[0,0,12],   belt:[0,0,70],  wave:0.4, solo:false },
  { xFrac:0.22, sc:1.4, skin:[30,55,75],  shirt:[0,0,92],  pants:[0,0,92],  hair:[30,70,25], belt:[0,0,70],  wave:0.3, solo:false },
  { xFrac:0.78, sc:1.4, skin:[30,55,75],  shirt:[0,0,92],  pants:[0,0,92],  hair:[30,70,25], belt:[0,0,70],  wave:0.3, solo:false },
  { xFrac:0.34, sc:1.6, skin:[22,42,90],  shirt:[0,0,90],  pants:[0,0,90],  hair:[350,55,50],belt:[0,0,70],  wave:0.2, solo:false },
  { xFrac:0.66, sc:1.6, skin:[22,42,90],  shirt:[0,0,90],  pants:[0,0,90],  hair:[350,55,50],belt:[0,0,70],  wave:0.2, solo:false },
];

// SOLOIST — front and center, biggest, white suit with gold accents
const soloist = { xFrac:0.50, sc:2.2, skin:[20,45,78], shirt:[0,0,100], pants:[0,0,100], hair:[0,0,8], belt:[45,95,100], wave:0.0, solo:true };

const dancers = [...backups, soloist];  // soloist drawn last = on top

// ── STAYING ALIVE CHOREOGRAPHY ──────────────────────────────
// 16-beat phrase (4 bars), each move = 1 beat, snaps on beat boundaries
// Sequence: point-R, point-L, point-R, point-L, strut-R, strut-L, strut-R, strut-L,
//           cross-point-R, cross-point-L, hip-walk-R, hip-walk-L, arm-sweep, arm-sweep, hold-pose, hold-pose
function getMove(beatInPhrase, subBeat, mirror) {
  const m = mirror;
  // subBeat: 0→1 within the beat, snapped timing
  const pop = subBeat < 0.15 ? 1 : 0;  // accent on downbeat
  const bounce = abs(sin(subBeat * PI)) * 6;  // one bounce per beat
  const snap = subBeat < 0.3 ? subBeat / 0.3 : 1;  // quick snap to position

  const b = beatInPhrase % 16;

  if (b < 4) {
    // TRAVOLTA DIAGONAL POINT — alternating R/L every beat
    const isRight = (b % 2 === 0);
    const side = isRight ? 1 : -1;
    return {
      dy: bounce,
      tilt: side * 0.06 * m * snap,
      hipX: side * 5 * m * snap,
      lArm: isRight ? -0.3 : lerp(0.3, -2.6, snap),
      rArm: isRight ? lerp(0.3, -2.6, snap) : -0.3,
      lLeg: side * 0.15 * snap,
      rLeg: -side * 0.1 * snap,
      spin: 0,
      crouch: 0,
      point: snap,
      pointHand: isRight ? 'r' : 'l',
    };
  }
  if (b < 8) {
    // STRUT — hip-walk with attitude, alternating weight shift
    const step = (b % 2 === 0) ? 1 : -1;
    const strut = sin(subBeat * PI);
    return {
      dy: strut * 4,
      tilt: step * 0.1 * m * strut,
      hipX: step * 7 * m * strut,
      lArm: -0.6 + step * 0.3 * strut,
      rArm: -0.6 - step * 0.3 * strut,
      lLeg: step * 0.2 * strut,
      rLeg: -step * 0.2 * strut,
      spin: 0,
      crouch: -strut * 3,
      point: 0,
    };
  }
  if (b < 12) {
    // CROSS-BODY POINT — point across body, lean into it
    const isRight = (b % 2 === 0);
    const side = isRight ? 1 : -1;
    return {
      dy: bounce,
      tilt: -side * 0.12 * m * snap,
      hipX: -side * 6 * m * snap,
      lArm: isRight ? -0.4 : lerp(0.2, -2.2, snap),
      rArm: isRight ? lerp(0.2, -2.2, snap) : -0.4,
      lLeg: -side * 0.12 * snap,
      rLeg: side * 0.08 * snap,
      spin: 0,
      crouch: snap * -4,
      point: snap,
      pointHand: isRight ? 'r' : 'l',
    };
  }
  if (b < 14) {
    // ARM SWEEP — both arms sweep from low to high in 2 beats
    const sweepT = ((b - 12) + subBeat) / 2;
    const armAngle = lerp(0.5, -2.8, sweepT);
    return {
      dy: bounce,
      tilt: sin(sweepT * PI) * 0.05 * m,
      hipX: sin(sweepT * PI) * 4 * m,
      lArm: armAngle,
      rArm: armAngle,
      lLeg: sin(sweepT * PI) * 0.1,
      rLeg: -sin(sweepT * PI) * 0.1,
      spin: 0,
      crouch: 0,
      point: sweepT > 0.8 ? 1 : 0,
      pointHand: 'both',
    };
  }
  // HOLD POSE — freeze at top of point, subtle bounce
  return {
    dy: bounce * 0.5,
    tilt: 0.04 * m,
    hipX: 3 * m,
    lArm: -2.6,
    rArm: -2.6,
    lLeg: 0.05,
    rLeg: -0.05,
    spin: 0,
    crouch: 0,
    point: 1,
    pointHand: 'both',
  };
}

// ── SOLOIST CHOREOGRAPHY — flashier, more varied, showstopper ──
function getSoloMove(beatInPhrase, subBeat) {
  const bounce = abs(sin(subBeat * PI)) * 8;
  const snap = subBeat < 0.2 ? subBeat / 0.2 : 1;
  const ease = subBeat < 0.5 ? 2*subBeat*subBeat : 1-pow(-2*subBeat+2,2)/2;
  const b = beatInPhrase % 32;  // 32-beat solo phrase (8 bars)

  if (b < 4) {
    // ICONIC STRUT FORWARD — hip sway, arms swinging opposite
    const side = (b % 2 === 0) ? 1 : -1;
    const stride = sin(subBeat * PI);
    return {
      dy: stride * 5,
      tilt: side * 0.14 * stride,
      hipX: side * 10 * stride,
      lArm: 0.4 - side * 0.6 * stride,
      rArm: 0.4 + side * 0.6 * stride,
      lLeg: side * 0.3 * stride,
      rLeg: -side * 0.25 * stride,
      spin: 0,
      crouch: -stride * 4,
      point: 0,
    };
  }
  if (b < 8) {
    // DIAGONAL POINT SEQUENCE — R up, L down, R across, L up (sharp snaps)
    const poses = [
      { lArm: -0.3, rArm: -2.8, tilt: 0.08, hipX: 6 },
      { lArm: 0.8, rArm: -0.3, tilt: -0.1, hipX: -5 },
      { lArm: -0.3, rArm: -1.8, tilt: -0.06, hipX: -4 },
      { lArm: -2.8, rArm: -0.3, tilt: 0.1, hipX: 5 },
    ];
    const pose = poses[(b - 4) % 4];
    return {
      dy: bounce,
      tilt: pose.tilt * snap,
      hipX: pose.hipX * snap,
      lArm: pose.lArm * snap + (1 - snap) * (-0.3),
      rArm: pose.rArm * snap + (1 - snap) * (-0.3),
      lLeg: 0.1 * snap,
      rLeg: -0.1 * snap,
      spin: 0,
      crouch: 0,
      point: snap,
      pointHand: (b % 2 === 0) ? 'r' : 'l',
    };
  }
  if (b < 12) {
    // SPIN + POINT — 2 beats spin, land into held point
    if (b < 10) {
      const spinT = ((b - 8) + subBeat) / 2;
      return {
        dy: 4,
        tilt: 0,
        hipX: 0,
        lArm: -1.8,
        rArm: -1.8,
        lLeg: 0,
        rLeg: 0,
        spin: spinT * TAU,
        crouch: 0,
        point: 0,
      };
    }
    // land into power point
    return {
      dy: bounce * 0.4,
      tilt: 0.1 * snap,
      hipX: 6 * snap,
      lArm: -0.4,
      rArm: -2.8 * snap,
      lLeg: 0.15 * snap,
      rLeg: -0.08,
      spin: 0,
      crouch: 0,
      point: snap,
      pointHand: 'r',
    };
  }
  if (b < 16) {
    // KNEE DIP + RISE — drop low beat 12-13, explode up 14-15
    const phase = b - 12;
    if (phase < 2) {
      const dropT = ((phase) + subBeat) / 2;
      const dip = pow(dropT, 1.5);
      return {
        dy: 0,
        tilt: 0,
        hipX: 0,
        lArm: lerp(-0.3, 0.6, dip),
        rArm: lerp(-0.3, 0.6, dip),
        lLeg: lerp(0.05, 0.5, dip),
        rLeg: lerp(-0.05, -0.5, dip),
        spin: 0,
        crouch: dip * 35,
        point: 0,
      };
    }
    const riseT = ((phase - 2) + subBeat) / 2;
    const rise = pow(riseT, 0.5);
    return {
      dy: -rise * 10,
      tilt: 0,
      hipX: 0,
      lArm: lerp(0.6, -2.6, rise),
      rArm: lerp(0.6, -2.6, rise),
      lLeg: lerp(0.5, 0, rise),
      rLeg: lerp(-0.5, 0, rise),
      spin: 0,
      crouch: lerp(35, 0, rise),
      point: rise > 0.7 ? 1 : 0,
      pointHand: 'both',
    };
  }
  if (b < 20) {
    // BODY ROLL — wave from knees up
    const rollT = subBeat;
    const side = (b % 2 === 0) ? 1 : -1;
    return {
      dy: sin(rollT * PI) * 6,
      tilt: side * sin(rollT * PI) * 0.12,
      hipX: side * sin(rollT * PI * 2) * 8,
      lArm: -1.0 + sin(rollT * PI) * 0.4,
      rArm: -1.0 - sin(rollT * PI) * 0.4,
      lLeg: sin(rollT * PI) * 0.08,
      rLeg: -sin(rollT * PI) * 0.08,
      spin: 0,
      crouch: sin(rollT * PI * 2) * 8,
      point: 0,
    };
  }
  if (b < 24) {
    // TRAVOLTA WALK — the classic sidewalk strut with alternating points
    const isRight = (b % 2 === 0);
    const side = isRight ? 1 : -1;
    const step = sin(subBeat * PI);
    return {
      dy: step * 7,
      tilt: side * 0.1 * step,
      hipX: side * 9 * step,
      lArm: isRight ? (-0.5 + step * 0.2) : lerp(0.3, -2.5, snap),
      rArm: isRight ? lerp(0.3, -2.5, snap) : (-0.5 + step * 0.2),
      lLeg: side * 0.25 * step,
      rLeg: -side * 0.2 * step,
      spin: 0,
      crouch: -step * 5,
      point: snap * 0.8,
      pointHand: isRight ? 'r' : 'l',
    };
  }
  if (b < 28) {
    // DOUBLE-TIME BOUNCE — fast alternating arm pumps
    const fast = sin(subBeat * TAU * 2);
    const side = fast > 0 ? 1 : -1;
    return {
      dy: abs(fast) * 8,
      tilt: fast * 0.05,
      hipX: fast * 4,
      lArm: -1.2 + fast * 0.6,
      rArm: -1.2 - fast * 0.6,
      lLeg: fast * 0.15,
      rLeg: -fast * 0.15,
      spin: 0,
      crouch: 0,
      point: 0,
    };
  }
  // FINALE HOLD — dramatic wide stance, both arms up
  return {
    dy: bounce * 0.3,
    tilt: sin(subBeat * PI) * 0.03,
    hipX: 0,
    lArm: -2.4,
    rArm: -2.4,
    lLeg: 0.2,
    rLeg: -0.2,
    spin: 0,
    crouch: 0,
    point: 1,
    pointHand: 'both',
  };
}

for (const d of dancers) {
  push();
  const x = width * d.xFrac;
  const baseY = floorY + (1 - d.sc / 2.2) * height * 0.08;
  const sc = d.sc;
  const mirror = d.xFrac > 0.5 ? -1 : 1;

  // cascading wave: front pair leads, back follows slightly after
  const db = beat - d.wave;
  let mv;
  if (d.solo) {
    const beatInPhrase = floor(db * 4) % 32;
    const subBeat = (db * 4) % 1;
    mv = getSoloMove(beatInPhrase, subBeat);
  } else {
    const beatInPhrase = floor(db * 4) % 16;
    const subBeat = (db * 4) % 1;
    mv = getMove(beatInPhrase, subBeat, mirror);
  }

  translate(x + mv.hipX * sc, baseY + mv.dy * sc + (mv.crouch || 0) * sc);
  rotate(mv.spin || 0);
  rotate(mv.tilt || 0);
  noStroke();

  // spotlight for soloist
  if (d.solo) {
    push(); blendMode(ADD);
    for (let r = 5; r > 0; r--) {
      fill(45, 30, 100, 6 + kick * 8);
      ellipse(0, -30*sc, (60 + r*18)*sc, (90 + r*20)*sc);
    }
    blendMode(BLEND); pop();
  }

  // shadow (stretches when crouching)
  const crouchAmt = (mv.crouch || 0) / 35;
  fill(0, 0, 0, d.solo ? 60 : 45);
  ellipse(0, 4*sc, (36 + crouchAmt*20)*sc, 8*sc);

  // floor glow
  push(); blendMode(ADD);
  fill(d.shirt[0], 45, 55, 14);
  ellipse(0, 3*sc, 50*sc, 10*sc);
  blendMode(BLEND); pop();

  // ── ROLLER SKATES ──
  // boot
  fill(0, 0, 95);
  rect(-13*sc, -6*sc, 11*sc, 8*sc, 2);
  rect(2*sc,   -6*sc, 11*sc, 8*sc, 2);
  // sole/plate
  fill(0, 0, 40);
  rect(-14*sc, 2*sc, 13*sc, 3*sc, 1);
  rect(1*sc,   2*sc, 13*sc, 3*sc, 1);
  // wheels (4 per skate)
  fill(d.solo ? 45 : 0, d.solo ? 80 : 0, d.solo ? 100 : 25);
  const wheelY = 5.5*sc;
  circle(-12*sc, wheelY, 3.5*sc);
  circle(-8*sc, wheelY, 3.5*sc);
  circle(-4*sc, wheelY, 3.5*sc);
  circle(-0.5*sc, wheelY, 3.5*sc);
  circle(3.5*sc, wheelY, 3.5*sc);
  circle(7.5*sc, wheelY, 3.5*sc);
  circle(11.5*sc, wheelY, 3.5*sc);
  circle(15*sc, wheelY, 3.5*sc);
  // wheel shine
  fill(0, 0, 100, 40);
  circle(-12*sc, wheelY - 0.8*sc, 1.5*sc);
  circle(-4*sc, wheelY - 0.8*sc, 1.5*sc);
  circle(3.5*sc, wheelY - 0.8*sc, 1.5*sc);
  circle(11.5*sc, wheelY - 0.8*sc, 1.5*sc);

  // ── BELL-BOTTOM LEGS ──
  push();
  rotate(mv.lLeg);
